INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$20a6a4ed$SATQ$, $SATQ$7463dd18-2479-45bf-b2a5-4f739fe1c34c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Anthropologist L&iacute;via Barbosa, of the Universidade Federal Fluminense in Brazil, <span aria-hidden="true">______</span><span class="sr-only">blank</span> food and sociability in contemporary Brazil&mdash;specifically, how foods such as <span lang="pt">cabidela</span> (a rice and rabbit dish) and <span lang="pt">churrasco</span> (a barbeque dish) function as central mechanisms in building social relationships, values, and identities.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"3c173537-2abe-46ea-a5dc-ead01ce00fcb","content":"<p>studies</p>"},{"id":"798b4823-2afd-442f-ba56-e63a3c3a22fc","content":"<p>are studying</p>"},{"id":"3bbf40cb-09de-4510-b6e5-bea2830ee578","content":"<p>have studied</p>"},{"id":"bf0efe8d-ec6f-49d4-a971-39d13e2ee994","content":"<p>study</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["3c173537-2abe-46ea-a5dc-ead01ce00fcb"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is subject-verb agreement. The singular verb "studies" agrees in number with the singular subject "anthropologist L&iacute;via Barbosa."</p><p>Choice B is incorrect because the plural verb "are studying" doesn&rsquo;t agree in number with the singular subject "anthropologist L&iacute;via Barbosa." Choice C is incorrect because the plural verb "have studied" doesn&rsquo;t agree in number with the singular subject "anthropologist L&iacute;via Barbosa." Choice D is incorrect because the plural verb "study" doesn&rsquo;t agree in number with the singular subject "anthropologist L&iacute;via Barbosa."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"20a6a4ed","external_id":"7463dd18-2479-45bf-b2a5-4f739fe1c34c","vaultid":null,"uId":"9cd3f2e8-2baa-4f8d-a974-aeea6d926f11","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Anthropologist L&iacute;via Barbosa, of the Universidade Federal Fluminense in Brazil, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> food and sociability in contemporary Brazil&mdash;specifically, how foods such as <span lang=\"pt\">cabidela</span> (a rice and rabbit dish) and <span lang=\"pt\">churrasco</span> (a barbeque dish) function as central mechanisms in building social relationships, values, and identities.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"3c173537-2abe-46ea-a5dc-ead01ce00fcb","content":"<p>studies</p>"},{"id":"798b4823-2afd-442f-ba56-e63a3c3a22fc","content":"<p>are studying</p>"},{"id":"3bbf40cb-09de-4510-b6e5-bea2830ee578","content":"<p>have studied</p>"},{"id":"bf0efe8d-ec6f-49d4-a971-39d13e2ee994","content":"<p>study</p>"}],"keys":["3c173537-2abe-46ea-a5dc-ead01ce00fcb"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is subject-verb agreement. The singular verb \"studies\" agrees in number with the singular subject \"anthropologist L&iacute;via Barbosa.\"</p><p>Choice B is incorrect because the plural verb \"are studying\" doesn&rsquo;t agree in number with the singular subject \"anthropologist L&iacute;via Barbosa.\" Choice C is incorrect because the plural verb \"have studied\" doesn&rsquo;t agree in number with the singular subject \"anthropologist L&iacute;via Barbosa.\" Choice D is incorrect because the plural verb \"study\" doesn&rsquo;t agree in number with the singular subject \"anthropologist L&iacute;via Barbosa.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$20ea68b7$SATQ$, $SATQ$ad45b060-13f3-4798-9b29-1165f8c5861f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>It can take time for proposed amendments to the US Constitution to become law. For example, the Twenty-Second Amendment, which limits the number of <span aria-hidden="true">______</span><span class="sr-only">blank</span> can serve, was first proposed in 1947 but wasn&rsquo;t approved by the required three-fourths majority of state legislatures until 1951.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"573fb562-8c13-4828-9d21-3ee382143ed9","content":"<p>terms presidents</p>"},{"id":"038dcdfe-838e-4648-b4f4-2dcd6b7fd86f","content":"<p>term&rsquo;s presidents</p>"},{"id":"49552583-5386-493a-8b93-eb024f97e620","content":"<p>term&rsquo;s president&rsquo;s</p>"},{"id":"dab55233-3c9e-47db-aeba-bdf184d526fe","content":"<p>terms president&rsquo;s</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["573fb562-8c13-4828-9d21-3ee382143ed9"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of plural nouns. The plural nouns "terms" and "presidents" correctly indicate that the amendment involves multiple terms and applies to presidents in general.</p><p>Choice B is incorrect because the context requires the plural noun "terms," not the singular possessive noun "term&rsquo;s." Choice C is incorrect because the context requires the plural nouns "terms" and "presidents," not the singular possessive nouns "term&rsquo;s" and "president&rsquo;s." Choice D is incorrect because the context requires the plural noun "presidents," not the singular possessive noun "president&rsquo;s."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"20ea68b7","external_id":"ad45b060-13f3-4798-9b29-1165f8c5861f","vaultid":null,"uId":"33db9b93-d988-4ea2-b408-2037e87e3640","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>It can take time for proposed amendments to the US Constitution to become law. For example, the Twenty-Second Amendment, which limits the number of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> can serve, was first proposed in 1947 but wasn&rsquo;t approved by the required three-fourths majority of state legislatures until 1951.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"573fb562-8c13-4828-9d21-3ee382143ed9","content":"<p>terms presidents</p>"},{"id":"038dcdfe-838e-4648-b4f4-2dcd6b7fd86f","content":"<p>term&rsquo;s presidents</p>"},{"id":"49552583-5386-493a-8b93-eb024f97e620","content":"<p>term&rsquo;s president&rsquo;s</p>"},{"id":"dab55233-3c9e-47db-aeba-bdf184d526fe","content":"<p>terms president&rsquo;s</p>"}],"keys":["573fb562-8c13-4828-9d21-3ee382143ed9"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of plural nouns. The plural nouns \"terms\" and \"presidents\" correctly indicate that the amendment involves multiple terms and applies to presidents in general.</p><p>Choice B is incorrect because the context requires the plural noun \"terms,\" not the singular possessive noun \"term&rsquo;s.\" Choice C is incorrect because the context requires the plural nouns \"terms\" and \"presidents,\" not the singular possessive nouns \"term&rsquo;s\" and \"president&rsquo;s.\" Choice D is incorrect because the context requires the plural noun \"presidents,\" not the singular possessive noun \"president&rsquo;s.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$21e58a83$SATQ$, $SATQ$5298757d-b328-4c83-880d-c22c895cef4a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Jetties&mdash;long, narrow structures that extend from a landmass into the water&mdash;are often constructed to protect coastlines from erosion. Jetties can sometimes have the opposite <span aria-hidden="true">______</span><span class="sr-only">blank</span> obstructing the natural flow of sand along the shore can lead to increased erosion in some areas.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"be4d9433-1729-40ac-a66a-164c17c21c44","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though<span data-ssml-say-as=\"characters\">;</span></p>"},{"id":"bf4bdb53-fe0b-451c-8d19-abf4cd77c58e","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though</p>"},{"id":"fd0722c1-cc42-4e4c-9a06-ce0d5942e0cc","content":"<p>effect<span data-ssml-say-as=\"characters\">;</span> though</p>"},{"id":"5ddce973-ad1e-4777-a5b4-79a00c33b218","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though<span data-ssml-say-as=\"characters\">,</span></p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["be4d9433-1729-40ac-a66a-164c17c21c44"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb "though" from the preceding main clause ("Jetties can sometimes have the opposite effect") and uses a semicolon to join the next main clause ("obstructing&hellip;areas") to the rest of the sentence. Further, placing the semicolon after "though" logically indicates that the information earlier in this sentence (that jetties can sometimes cause erosion) is contrary to what might be assumed from the information in the previous sentence (that jetties are often constructed for the purpose of protecting coastlines from erosion).</p><p>Choice B is incorrect because it fails to mark the boundary between the two main clauses with appropriate punctuation. With "though&hellip;areas" functioning as a subordinate clause following the comma, this choice illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following "though" supports the previous claim about the erosive effects of jetties. Choice C is incorrect because it&rsquo;s not conventional to use a semicolon in this way to separate a main clause from a dependent clause. Further, it illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following "though" supports the previous claim about the erosive effects of jetties. Choice D is incorrect because it results in a comma splice. Commas can&rsquo;t be used in this way to set off a supplementary word or phrase between two main clauses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"21e58a83","external_id":"5298757d-b328-4c83-880d-c22c895cef4a","vaultid":null,"uId":"8437420c-68f4-43e5-9f4c-1751c23f734d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Jetties&mdash;long, narrow structures that extend from a landmass into the water&mdash;are often constructed to protect coastlines from erosion. Jetties can sometimes have the opposite <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> obstructing the natural flow of sand along the shore can lead to increased erosion in some areas.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"be4d9433-1729-40ac-a66a-164c17c21c44","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though<span data-ssml-say-as=\"characters\">;</span></p>"},{"id":"bf4bdb53-fe0b-451c-8d19-abf4cd77c58e","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though</p>"},{"id":"fd0722c1-cc42-4e4c-9a06-ce0d5942e0cc","content":"<p>effect<span data-ssml-say-as=\"characters\">;</span> though</p>"},{"id":"5ddce973-ad1e-4777-a5b4-79a00c33b218","content":"<p>effect<span data-ssml-say-as=\"characters\">,</span> though<span data-ssml-say-as=\"characters\">,</span></p>"}],"keys":["be4d9433-1729-40ac-a66a-164c17c21c44"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb \"though\" from the preceding main clause (\"Jetties can sometimes have the opposite effect\") and uses a semicolon to join the next main clause (\"obstructing&hellip;areas\") to the rest of the sentence. Further, placing the semicolon after \"though\" logically indicates that the information earlier in this sentence (that jetties can sometimes cause erosion) is contrary to what might be assumed from the information in the previous sentence (that jetties are often constructed for the purpose of protecting coastlines from erosion).</p><p>Choice B is incorrect because it fails to mark the boundary between the two main clauses with appropriate punctuation. With \"though&hellip;areas\" functioning as a subordinate clause following the comma, this choice illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following \"though\" supports the previous claim about the erosive effects of jetties. Choice C is incorrect because it&rsquo;s not conventional to use a semicolon in this way to separate a main clause from a dependent clause. Further, it illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following \"though\" supports the previous claim about the erosive effects of jetties. Choice D is incorrect because it results in a comma splice. Commas can&rsquo;t be used in this way to set off a supplementary word or phrase between two main clauses.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$265e7f4c$SATQ$, $SATQ$8fd2d194-8701-43a6-b098-7393b886f656$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The Globe Theatre in London is a reconstruction of the famed venue where many of Shakespeare&rsquo;s plays were first performed. In 1613, a prop cannon <span aria-hidden="true">______</span><span class="sr-only">blank</span> during a performance and ignited the Globe&rsquo;s thatched roof. No one was hurt, but in two hours the original Globe was gone.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"80ee4af8-f0a6-4a31-bc92-ab6da7d95019","content":"<p>malfunctions</p>"},{"id":"79501080-dbd0-4480-abcc-67e81d44151f","content":"<p>will malfunction</p>"},{"id":"9b5228cf-f58a-45e8-bf9b-27c77a4bb333","content":"<p>has malfunctioned</p>"},{"id":"79d5b6a8-4da6-413a-b89a-0402f09f9a50","content":"<p>malfunctioned</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["79d5b6a8-4da6-413a-b89a-0402f09f9a50"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past tense verb "malfunctioned" is consistent with the other past tense verbs ("ignited" and "was") used to describe the destruction of the original Globe Theatre.</p><p>Choice A is incorrect because the present tense verb "malfunctions" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice B is incorrect because the future tense verb "will malfunction" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice C is incorrect because the present perfect tense verb "has malfunctioned" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"265e7f4c","external_id":"8fd2d194-8701-43a6-b098-7393b886f656","vaultid":null,"uId":"f6b8c025-2a44-4b46-a50f-bd39e66e733a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The Globe Theatre in London is a reconstruction of the famed venue where many of Shakespeare&rsquo;s plays were first performed. In 1613, a prop cannon <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> during a performance and ignited the Globe&rsquo;s thatched roof. No one was hurt, but in two hours the original Globe was gone.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"80ee4af8-f0a6-4a31-bc92-ab6da7d95019","content":"<p>malfunctions</p>"},{"id":"79501080-dbd0-4480-abcc-67e81d44151f","content":"<p>will malfunction</p>"},{"id":"9b5228cf-f58a-45e8-bf9b-27c77a4bb333","content":"<p>has malfunctioned</p>"},{"id":"79d5b6a8-4da6-413a-b89a-0402f09f9a50","content":"<p>malfunctioned</p>"}],"keys":["79d5b6a8-4da6-413a-b89a-0402f09f9a50"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past tense verb \"malfunctioned\" is consistent with the other past tense verbs (\"ignited\" and \"was\") used to describe the destruction of the original Globe Theatre.</p><p>Choice A is incorrect because the present tense verb \"malfunctions\" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice B is incorrect because the future tense verb \"will malfunction\" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice C is incorrect because the present perfect tense verb \"has malfunctioned\" isn&rsquo;t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$267a13e2$SATQ$, $SATQ$1272a41a-f321-46f0-8b6f-a016b8d2916a$SATQ$::uuid, $SATQ$4488c946-2780-4796-acee-fda2ad02fea9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In 2010, archaeologist Noel Hidalgo Tan was visiting the twelfth-century temple of Angkor Wat in Cambodia when he noticed markings of red paint on the temple <span aria-hidden="true">______</span><span class="sr-only">blank</span> the help of digital imaging techniques, he discovered the markings to be part of an elaborate mural containing over 200 paintings. &nbsp;&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"06f1695c-acbf-4749-8893-db604c46cc42","content":"<p>walls, with</p>"},{"id":"67420edf-0f5f-4534-bfd4-0e2b45caa290","content":"<p>walls with&nbsp;</p>"},{"id":"7529df6d-c399-40dc-b2cc-62d7ee186a16","content":"<p>walls so with&nbsp;</p>"},{"id":"897e8b81-a3fb-40b0-8b9d-2b4a1525e4ae","content":"<p>walls. With</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["897e8b81-a3fb-40b0-8b9d-2b4a1525e4ae"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;walls&rdquo; is used correctly to mark the boundary between the first sentence (&ldquo;In...walls&rdquo;) and the second sentence (&ldquo;With&hellip;techniques&rdquo;), which starts with a supplementary phrase. </p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice B is incorrect because it results in a run-on sentence. The sentences (&ldquo;In...walls&rdquo; and &ldquo;with...paintings&rdquo;) are fused without punctuation and/or a conjunction. Choice C is incorrect. Without a comma preceding it, the conjunction &ldquo;so&rdquo; can&rsquo;t be used in this way to join sentences. </p>$SATQ$, false, 0, $SATQ$OSP-601-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$c38d7865-ed27-4117-8fa0-9174b6cf2e55$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"267a13e2","external_id":"1272a41a-f321-46f0-8b6f-a016b8d2916a","vaultid":"4488c946-2780-4796-acee-fda2ad02fea9","uId":"82b20e63-e01b-4f12-af46-f234dffb0335","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In 2010, archaeologist Noel Hidalgo Tan was visiting the twelfth-century temple of Angkor Wat in Cambodia when he noticed markings of red paint on the temple <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the help of digital imaging techniques, he discovered the markings to be part of an elaborate mural containing over 200 paintings. &nbsp;&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"06f1695c-acbf-4749-8893-db604c46cc42","content":"<p>walls, with</p>"},{"id":"67420edf-0f5f-4534-bfd4-0e2b45caa290","content":"<p>walls with&nbsp;</p>"},{"id":"7529df6d-c399-40dc-b2cc-62d7ee186a16","content":"<p>walls so with&nbsp;</p>"},{"id":"897e8b81-a3fb-40b0-8b9d-2b4a1525e4ae","content":"<p>walls. With</p>"}],"keys":["897e8b81-a3fb-40b0-8b9d-2b4a1525e4ae"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;walls&rdquo; is used correctly to mark the boundary between the first sentence (&ldquo;In...walls&rdquo;) and the second sentence (&ldquo;With&hellip;techniques&rdquo;), which starts with a supplementary phrase. </p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice B is incorrect because it results in a run-on sentence. The sentences (&ldquo;In...walls&rdquo; and &ldquo;with...paintings&rdquo;) are fused without punctuation and/or a conjunction. Choice C is incorrect. Without a comma preceding it, the conjunction &ldquo;so&rdquo; can&rsquo;t be used in this way to join sentences. </p>","parenttemplatename":"OSP-601-SEC","parenttemplateid":"","templateclusterid":"c38d7865-ed27-4117-8fa0-9174b6cf2e55","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959338,"updateDate":1691007959338}$SATQ$::jsonb, 1691007959338, 1691007959338),
    ($SATQ$26c8c88c$SATQ$, $SATQ$03a256b6-5176-4252-90e5-202271ae9743$SATQ$::uuid, $SATQ$21d1b200-2cd0-4754-9e35-2648d90377b5$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>About 70,000 meteorites have been found on Earth. Although most meteorites are fragments of <span aria-hidden="true">______</span><span class="sr-only">blank</span> hundred have been identified as being from the Moon or Mars.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0ac17a0e-7612-44ab-b520-b2678a3bccbe","content":"<p>asteroids. Several</p>"},{"id":"1d293718-48c7-4817-9f11-831ccac8f45e","content":"<p>asteroids, several</p>"},{"id":"7dcf9fe6-fa82-4963-923c-f2ab2ba10a54","content":"<p>asteroids; several</p>"},{"id":"8cd819bb-1c3d-4dae-bcfc-73fee4af4f2f","content":"<p>asteroids: several</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["1d293718-48c7-4817-9f11-831ccac8f45e"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This choice uses a comma to correctly separate the dependent clause "although&hellip;asteroids" from the independent clause "several hundred have been&hellip;Mars."</p><p>Choice A is incorrect. This choice results in a sentence fragment. "Although&hellip;asteroids" is a dependent clause. It can&rsquo;t stand on its own as a sentence, which means it can&rsquo;t end in a period. Choice C is incorrect. This choice results in a punctuation error. "Although&hellip;asteroids" is a dependent clause and can&rsquo;t be joined to the independent clause "several hundred have been&hellip;Mars" with a semicolon. A semicolon can only join two independent clauses. Choice D is incorrect. This choice creates a punctuation error. A colon can only come after an independent clause, but "although&hellip;asteroids" is a dependent clause.</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-E009$SATQ$, $SATQ$$SATQ$, $SATQ$b124bb46-98fe-491e-af55-525b8e59ff13$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"26c8c88c","external_id":"03a256b6-5176-4252-90e5-202271ae9743","vaultid":"21d1b200-2cd0-4754-9e35-2648d90377b5","uId":"539cda56-b0d6-4417-9a0d-b403e37162f5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>About 70,000 meteorites have been found on Earth. Although most meteorites are fragments of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> hundred have been identified as being from the Moon or Mars.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0ac17a0e-7612-44ab-b520-b2678a3bccbe","content":"<p>asteroids. Several</p>"},{"id":"1d293718-48c7-4817-9f11-831ccac8f45e","content":"<p>asteroids, several</p>"},{"id":"7dcf9fe6-fa82-4963-923c-f2ab2ba10a54","content":"<p>asteroids; several</p>"},{"id":"8cd819bb-1c3d-4dae-bcfc-73fee4af4f2f","content":"<p>asteroids: several</p>"}],"keys":["1d293718-48c7-4817-9f11-831ccac8f45e"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This choice uses a comma to correctly separate the dependent clause \"although&hellip;asteroids\" from the independent clause \"several hundred have been&hellip;Mars.\"</p><p>Choice A is incorrect. This choice results in a sentence fragment. \"Although&hellip;asteroids\" is a dependent clause. It can&rsquo;t stand on its own as a sentence, which means it can&rsquo;t end in a period. Choice C is incorrect. This choice results in a punctuation error. \"Although&hellip;asteroids\" is a dependent clause and can&rsquo;t be joined to the independent clause \"several hundred have been&hellip;Mars\" with a semicolon. A semicolon can only join two independent clauses. Choice D is incorrect. This choice creates a punctuation error. A colon can only come after an independent clause, but \"although&hellip;asteroids\" is a dependent clause.</p>","parenttemplatename":"OSP-KA-BOU-E009","parenttemplateid":"","templateclusterid":"b124bb46-98fe-491e-af55-525b8e59ff13","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$2784cbaf$SATQ$, $SATQ$c262c2cf-76aa-4333-8ded-17badecce917$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>To fully describe the motion of an object requires knowing each of five <span aria-hidden="true">______</span><span class="sr-only">blank</span> movement: displacement, time, initial velocity, final velocity, and acceleration. These are called kinematic variables. &nbsp;&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9b366a36-75a4-4bde-a31d-d16f4d8d9653","content":"<p>variable&rsquo;s that characterize objects&rsquo;</p>"},{"id":"9d9a74f6-a52b-413f-900e-587c8cfd85c9","content":"<p>variables that characterize objects&rsquo;</p>"},{"id":"2819c938-4e31-4398-9ccd-57be0d402824","content":"<p>variables that characterize object&rsquo;s</p>"},{"id":"81198ba3-8aa9-45aa-9fd3-daa0721cdf9d","content":"<p>variables that characterize objects</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["9d9a74f6-a52b-413f-900e-587c8cfd85c9"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The conventions being tested are the use of plural and possessive nouns. The plural noun "variables" correctly indicates that there are multiple variables, and the plural possessive noun "objects&rsquo;" correctly indicates that the movement of objects in general is being discussed.</p><p>Choice A is incorrect because the context requires the plural noun "variables," not the singular possessive noun "variable&rsquo;s." Choice C is incorrect because the context requires the plural possessive noun "objects&rsquo;," not the singular possessive noun "object&rsquo;s." Choice D is incorrect because the context requires the plural possessive noun "objects&rsquo;," not the plural noun "objects."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2784cbaf","external_id":"c262c2cf-76aa-4333-8ded-17badecce917","vaultid":null,"uId":"607aafeb-dc36-4bff-ba14-706933074d63","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>To fully describe the motion of an object requires knowing each of five <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> movement: displacement, time, initial velocity, final velocity, and acceleration. These are called kinematic variables. &nbsp;&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9b366a36-75a4-4bde-a31d-d16f4d8d9653","content":"<p>variable&rsquo;s that characterize objects&rsquo;</p>"},{"id":"9d9a74f6-a52b-413f-900e-587c8cfd85c9","content":"<p>variables that characterize objects&rsquo;</p>"},{"id":"2819c938-4e31-4398-9ccd-57be0d402824","content":"<p>variables that characterize object&rsquo;s</p>"},{"id":"81198ba3-8aa9-45aa-9fd3-daa0721cdf9d","content":"<p>variables that characterize objects</p>"}],"keys":["9d9a74f6-a52b-413f-900e-587c8cfd85c9"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The conventions being tested are the use of plural and possessive nouns. The plural noun \"variables\" correctly indicates that there are multiple variables, and the plural possessive noun \"objects&rsquo;\" correctly indicates that the movement of objects in general is being discussed.</p><p>Choice A is incorrect because the context requires the plural noun \"variables,\" not the singular possessive noun \"variable&rsquo;s.\" Choice C is incorrect because the context requires the plural possessive noun \"objects&rsquo;,\" not the singular possessive noun \"object&rsquo;s.\" Choice D is incorrect because the context requires the plural possessive noun \"objects&rsquo;,\" not the plural noun \"objects.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$28166dc6$SATQ$, $SATQ$f65b2467-248f-4fb2-926c-387de770ef8e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In knot theory (the mathematical study of curved, closed loops), knots are characterized by their crossing numbers&mdash;that is, the number of times the knotted thread crosses over itself. The trefoil knot and the figure-eight knot, each with a crossing number below five, <span aria-hidden="true">______</span><span class="sr-only">blank</span> among the simplest possible knots with the fewest number of crossings.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"48b362a8-da8a-4da7-a268-e5cdce3efbe3","content":"<p>was</p>"},{"id":"fd51030a-2a8a-42b1-bd6d-d885b8b7c31a","content":"<p>are</p>"},{"id":"86f70419-f687-4155-8da5-37ad6855cd8b","content":"<p>has been</p>"},{"id":"68169f67-25fb-4dfc-8df5-be0f2a3ae34f","content":"<p>is</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["fd51030a-2a8a-42b1-bd6d-d885b8b7c31a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The plural verb "are" agrees in number with the plural compound subject "the trefoil knot and the figure-eight knot." The two types of knots joined by "and" function as a plural subject and thus require a plural verb.</p><p>Choice A is incorrect because the singular verb "was" doesn&rsquo;t agree in number with the plural compound subject "the trefoil knot and the figure-eight knot." Choice C is incorrect because the singular verb "has been" doesn&rsquo;t agree in number with the plural compound subject "the trefoil knot and the figure-eight knot." Choice D is incorrect because the singular verb "is" doesn&rsquo;t agree in number with the plural compound subject "the trefoil knot and the figure-eight knot."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"28166dc6","external_id":"f65b2467-248f-4fb2-926c-387de770ef8e","vaultid":null,"uId":"b1e9fe37-7c8f-4c02-9b1c-a4ba2bbdc047","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In knot theory (the mathematical study of curved, closed loops), knots are characterized by their crossing numbers&mdash;that is, the number of times the knotted thread crosses over itself. The trefoil knot and the figure-eight knot, each with a crossing number below five, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> among the simplest possible knots with the fewest number of crossings.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"48b362a8-da8a-4da7-a268-e5cdce3efbe3","content":"<p>was</p>"},{"id":"fd51030a-2a8a-42b1-bd6d-d885b8b7c31a","content":"<p>are</p>"},{"id":"86f70419-f687-4155-8da5-37ad6855cd8b","content":"<p>has been</p>"},{"id":"68169f67-25fb-4dfc-8df5-be0f2a3ae34f","content":"<p>is</p>"}],"keys":["fd51030a-2a8a-42b1-bd6d-d885b8b7c31a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The plural verb \"are\" agrees in number with the plural compound subject \"the trefoil knot and the figure-eight knot.\" The two types of knots joined by \"and\" function as a plural subject and thus require a plural verb.</p><p>Choice A is incorrect because the singular verb \"was\" doesn&rsquo;t agree in number with the plural compound subject \"the trefoil knot and the figure-eight knot.\" Choice C is incorrect because the singular verb \"has been\" doesn&rsquo;t agree in number with the plural compound subject \"the trefoil knot and the figure-eight knot.\" Choice D is incorrect because the singular verb \"is\" doesn&rsquo;t agree in number with the plural compound subject \"the trefoil knot and the figure-eight knot.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$29c9be28$SATQ$, $SATQ$904e43e0-7683-4367-bca6-125ad4829d8b$SATQ$::uuid, $SATQ$a6b6247b-b40f-45eb-9c40-97f21720d200$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>To survive when water is scarce, embryos inside African turquoise killifish eggs <span aria-hidden="true">______</span><span class="sr-only">blank</span> a dormant state known as diapause. In this state, embryonic development is paused for as long as two years&mdash;longer than the life span of an adult killifish.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"aa6a06b8-a6dd-4631-af70-33c75409c94e","content":"<p>enter</p>"},{"id":"da4c2e4e-eb6d-45b7-9d9d-501b4dfd006d","content":"<p>to enter</p>"},{"id":"debf27b6-4cba-43e5-8e46-44dc0465fd0c","content":"<p>having entered</p>"},{"id":"64a8af66-89e6-4ff6-a578-ca99e7041b8d","content":"<p>entering</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["aa6a06b8-a6dd-4631-af70-33c75409c94e"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;embryos&rdquo;), and this choice supplies the clause with the finite present tense verb &ldquo;enter&rdquo; to indicate how the embryos achieve diapause. </p><p>Choice B is incorrect because the nonfinite to-infinitive &ldquo;to enter&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle &ldquo;having entered&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite participle &ldquo;entering&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>$SATQ$, false, 0, $SATQ$OSP-647-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$de89698f-f612-4f40-9697-71d43ae4f708$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"29c9be28","external_id":"904e43e0-7683-4367-bca6-125ad4829d8b","vaultid":"a6b6247b-b40f-45eb-9c40-97f21720d200","uId":"18f0fc9d-00c7-4e6b-8233-2440e06217e2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>To survive when water is scarce, embryos inside African turquoise killifish eggs <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a dormant state known as diapause. In this state, embryonic development is paused for as long as two years&mdash;longer than the life span of an adult killifish.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"aa6a06b8-a6dd-4631-af70-33c75409c94e","content":"<p>enter</p>"},{"id":"da4c2e4e-eb6d-45b7-9d9d-501b4dfd006d","content":"<p>to enter</p>"},{"id":"debf27b6-4cba-43e5-8e46-44dc0465fd0c","content":"<p>having entered</p>"},{"id":"64a8af66-89e6-4ff6-a578-ca99e7041b8d","content":"<p>entering</p>"}],"keys":["aa6a06b8-a6dd-4631-af70-33c75409c94e"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, &ldquo;embryos&rdquo;), and this choice supplies the clause with the finite present tense verb &ldquo;enter&rdquo; to indicate how the embryos achieve diapause. </p><p>Choice B is incorrect because the nonfinite to-infinitive &ldquo;to enter&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle &ldquo;having entered&rdquo; doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because the nonfinite participle &ldquo;entering&rdquo; doesn&rsquo;t supply the main clause with a finite verb. </p>","parenttemplatename":"OSP-647-SEC","parenttemplateid":"","templateclusterid":"de89698f-f612-4f40-9697-71d43ae4f708","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$2b512e65$SATQ$, $SATQ$a95027cf-d330-49f3-9436-0f55c8a56c5a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Eli Eisenberg, a genetics expert at Tel Aviv University in Israel, recently discovered that <span aria-hidden="true">______</span><span class="sr-only">blank</span> have a special genetic ability called RNA editing that confers evolutionary advantages.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"fc233cfa-2cb9-4377-bac1-62bec4adff88","content":"<p>cephalopods<span data-ssml-say-as=\"characters\">,</span> ocean dwellers that include the squid<span data-ssml-say-as=\"characters\">,</span> the octopus<span data-ssml-say-as=\"characters\">,</span> and the cuttlefish</p>"},{"id":"7bf21ba8-45b0-4d57-a34c-ae48537c0c24","content":"<p>cephalopods<span data-ssml-say-as=\"characters\">&mdash;</span>ocean dwellers<span data-ssml-say-as=\"characters\">&mdash;</span>that include the squid<span data-ssml-say-as=\"characters\">,</span> the octopus<span data-ssml-say-as=\"characters\">,</span> and the cuttlefish<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"b62ad747-6d50-4927-8abb-75c4dc4c6c4c","content":"<p>cephalopods<span data-ssml-say-as=\"characters\">,</span> ocean dwellers that include<span data-ssml-say-as=\"characters\">:</span> the squid<span data-ssml-say-as=\"characters\">,</span> the octopus<span data-ssml-say-as=\"characters\">,</span> and the cuttlefish<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"8cc3b312-47ec-46d7-b5cf-d8eadfe46d22","content":"<p>cephalopods<span data-ssml-say-as=\"characters\">&mdash;</span>ocean dwellers that include the squid<span data-ssml-say-as=\"characters\">,</span> the octopus<span data-ssml-say-as=\"characters\">,</span> and the cuttlefish<span data-ssml-say-as=\"characters\">&mdash;</span></p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8cc3b312-47ec-46d7-b5cf-d8eadfe46d22"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. In this choice, the dash after "cephalopods" pairs with the dash after "cuttlefish" to clearly separate the supplementary element "ocean dwellers that include the squid, the octopus, and the cuttlefish" from the rest of the sentence. This supplementary element functions to explain what cephalopods are, and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element that explains what cephalopods are from the rest of the sentence. Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element that explains what cephalopods are from the rest of the sentence. Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element that explains what cephalopods are from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"2b512e65","external_id":"a95027cf-d330-49f3-9436-0f55c8a56c5a","vaultid":null,"uId":"5bf0c440-4daf-4fb6-bc2b-e43b0943ac55","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Eli Eisenberg, a genetics expert at Tel Aviv University in Israel, recently discovered that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> have a special genetic ability called RNA editing that confers evolutionary advantages.</p>","ste